import { describe, it, expect } from "vitest";
import { createChaseCamera } from "./chase-camera.js";

const dot = (a: number[], b: number[]) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
// world matrix column accessors (column-major: col c = m[4c..4c+2])
const col = (m: ArrayLike<number>, c: number) => [m[4 * c], m[4 * c + 1], m[4 * c + 2]];

describe("chase camera", () => {
    it("starts upright and looks at target", () => {
        const c = createChaseCamera({ x: 0, y: 2, z: -10 }, { x: 0, y: 0, z: 0 });
        const y = col(c.camera.worldMatrix, 1);
        expect(y[1]).toBeCloseTo(1, 6);
    });
    it("banks to a rolled up, stays looking at target, z-axis unchanged", () => {
        const eye = { x: 1, y: 2, z: -10 }, target = { x: 0, y: 0, z: 0 };
        const c = createChaseCamera(eye, target);
        const z0 = col(c.camera.worldMatrix, 2);
        const want = { x: 1, y: 0, z: 0 };
        c.bank(want);
        const m = c.camera.worldMatrix;
        const z = col(m, 2), y = col(m, 1);
        expect(dot(z, z0)).toBeCloseTo(1, 6);
        const f = [-1, -2, 10]; const fl = Math.hypot(...f); const fn = f.map(v => v / fl);
        expect(dot(z, fn)).toBeCloseTo(1, 6);
        // picture up projects onto requested up direction
        const ex = dot([1,0,0], y);
        expect(ex).toBeGreaterThan(0.99); // roughly rolled to +X
        expect(dot(y, fn)).toBeCloseTo(0, 6);
        expect(Math.hypot(...y)).toBeCloseTo(1, 6);
    });
    it("up along line of sight keeps previous roll", () => {
        const c = createChaseCamera({ x: 0, y: 0, z: -10 }, { x: 0, y: 0, z: 0 });
        c.bank({ x: 1, y: 0, z: 0 });
        const before = Array.from(c.camera.worldMatrix);
        const f = [0, 0, 1];
        c.bank({ x: 0, y: 0, z: 1 });
        c.bank({ x: 0, y: 0, z: -1 });
        c.bank({ x: 1e-9, y: 0, z: -1 });
        expect(Array.from(c.camera.worldMatrix)).toEqual(before);
        void f;
    });
    it("float32 exact-parallel up keeps roll", () => {
        const eye = { x: 3, y: 4, z: -12 }, target = { x: 0, y: 0, z: 0 };
        const c = createChaseCamera(eye, target);
        c.bank({ x: 0, y: 1, z: 0 });
        const before = Array.from(c.camera.worldMatrix);
        const d = [-3, -4, 12]; const l = Math.hypot(...d);
        const u = d.map(v => Math.fround(v / l));
        c.bank({ x: u[0], y: u[1], z: u[2] });
        expect(Array.from(c.camera.worldMatrix)).toEqual(before);
    });
    it("eye on target does not throw", () => {
        const c = createChaseCamera({ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 0 });
        expect(() => c.bank({ x: 1, y: 0, z: 0 })).not.toThrow();
    });
});
